const items = $input.all();
const infoProyectos = items.filter(i => i.json._sheet === 'InfoProyectos').map(i => { const { _sheet, ...rest } = i.json; return rest; });
const backlog = items.filter(i => i.json._sheet === 'Backlog').map(i => { const { _sheet, ...rest } = i.json; return rest; });
const fuente = $('Fuente Actual Forecast').first(0, $runIndex).json._fuente;
return [{ json: { _fuente: fuente, InfoProyectos: infoProyectos, Backlog: backlog }, pairedItem: { item: 0 } }];

function normalizarNombre(nombre) {
  return String(nombre || '')
    .normalize('NFD').replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function calcularClave(row) {
  const pa = row['# PA'];
  if (pa !== null && pa !== undefined && String(pa).trim() !== '' && String(pa) !== '#N/A') {
    return 'pa:' + String(pa).trim();
  }
  return 'nombre:' + normalizarNombre(row['Nombre del Proyecto']);
}

function excelSerialToDate(serial) {
  return new Date(Date.UTC(1899, 11, 30) + serial * 86400000);
}

function parseFechaFin(v) {
  if (v instanceof Date) return v;
  if (typeof v === 'number') return excelSerialToDate(v);
  if (typeof v === 'string') {
    // 'Fecha fin' viene en formato MM/DD/YYYY (americano), confirmado con datos reales
    // (ej. '12/14/2026' solo es valido como mes/dia, nunca dia/mes).
    const m = v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) {
      const mes = +m[1], dia = +m[2], anio = +m[3];
      if (mes < 1 || mes > 12 || dia < 1 || dia > 31) return null;
      const fecha = new Date(Date.UTC(anio, mes - 1, dia));
      if (fecha.getUTCMonth() !== mes - 1 || fecha.getUTCDate() !== dia) return null;
      return fecha;
    }
  }
  return null;
}

function calcularEstadoYDias(fechaFinRaw, hoyStr) {
  const fechaFin = parseFechaFin(fechaFinRaw);
  if (!fechaFin) return { dias: null, estado: null };
  const hoy = new Date(hoyStr + 'T00:00:00Z');
  const dias = Math.round((fechaFin - hoy) / 86400000);
  let estado;
  if (dias <= 0) estado = 'Contrato vencido';
  else if (dias <= 30) estado = 'Contrato vence en menos de 30dias';
  else if (dias < 60) estado = 'Contrato finaliza en menos de 60dias';
  else estado = 'Contrato vigente';
  return { dias, estado };
}


// Sin la columna del Excel no hay cómo saber los meses transcurridos: hace
// falta la fecha de inicio, que no viene. Mejor vacío que un número inventado.
function calcularMesesTranscurridos() {
  return null;
}

function esVacia(row) {
  const pa = row['# PA'];
  const nombre = row['Nombre del Proyecto'];
  const paVacio = pa === null || pa === undefined || String(pa).trim() === '' || String(pa) === '#N/A';
  const nombreTexto = nombre === null || nombre === undefined ? '' : String(nombre).trim().toLowerCase();
  const nombreVacio = nombreTexto === '' || nombreTexto === 'n/a' || nombreTexto === '#n/a' || nombreTexto === 'na';
  return paVacio && nombreVacio;
}

const data = $json;
const infoSinVacias = (data.InfoProyectos || []).filter(row => !esVacia(row));
const backlogSinVacias = (data.Backlog || []).filter(row => !esVacia(row));
const filasVaciasDescartadas = (data.InfoProyectos || []).length - infoSinVacias.length
  + (data.Backlog || []).length - backlogSinVacias.length;
const fechaReferencia = new Date().toISOString().slice(0, 10);

function formatearFechaISO(fecha) {
  if (!fecha) return null;
  return fecha.toISOString().slice(0, 10);
}

const infoEnriquecido = infoSinVacias.map(row => {
  const { dias, estado } = calcularEstadoYDias(row['Fecha fin'], fechaReferencia);
  const fechaFinParsed = parseFechaFin(row['Fecha fin']);
  return {
    ...row,
    _clave: calcularClave(row),
    _dias_para_vencimiento: dias,
    _estado_contrato: estado,
    _fecha_fin_iso: formatearFechaISO(fechaFinParsed),
    _meses_transcurridos: row['Meses transcurridos'] !== null && row['Meses transcurridos'] !== undefined && String(row['Meses transcurridos']).trim() !== '' ? row['Meses transcurridos'] : calcularMesesTranscurridos(row['Fecha fin'], fechaReferencia),
    _executive_watchlist: row['Executive Watchlist'],
    _project_status: row['Project Status'],
  };
});

const backlogEnriquecido = backlogSinVacias.map(row => ({ ...row, _clave: calcularClave(row) }));

return [{ json: { ...data, InfoProyectos: infoEnriquecido, Backlog: backlogEnriquecido, fechaReferencia, filasVaciasDescartadas } }];

function esNumero(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return false;
  return !isNaN(Number(v));
}

const data = $json;
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];
const errores = [];
if (!data._esquema_forecast) errores.push('Falta normalizar el forecast antes de validar.');
if (data._esquema_forecast?.faltantes.length) {
  errores.push('Columnas requeridas ausentes para FY' + data._fuente.anio_forecast + ': ' + data._esquema_forecast.faltantes.join(', '));
}
if (data._esquema_forecast?.cabeceraOtroAnio) errores.push('El archivo contiene la cabecera de backlog de otro año. Revisa la fuente configurada.');
for (const campo of ['valor_of','acumulado_anterior','backlog','total_ejecutado']) {
  if (!backlog.some(r => typeof r._forecast?.[campo] === 'number' && Number.isFinite(r._forecast[campo]))) {
    errores.push('Sin valores numericos para ' + campo + '. No se permite una carga financiera completamente vacia.');
  }
}
for (const [hoja, filas] of [['Info Proyectos', info], ['BackLog NOLA', backlog]]) {
  if (new Set(filas.map(r => r._clave)).size !== filas.length) errores.push('Llaves duplicadas en ' + hoja + '.');
}

if (info.length < 10) errores.push(`Muy pocos proyectos en Info Proyectos: ${info.length}`);
if (backlog.length < 10) errores.push(`Muy pocos proyectos en Backlog: ${backlog.length}`);

const clavesInfo = new Set(info.map(r => r._clave));
const sinCruce = backlog.filter(r => !clavesInfo.has(r._clave));
const cruzan = backlog.length - sinCruce.length;
const pctCruce = backlog.length ? cruzan / backlog.length : 0;
if (pctCruce < 0.95) {
  const ejemplos = sinCruce.slice(0, 15).map(r => `${r._clave} (${r['Nombre del Proyecto'] || 'sin nombre'})`).join('; ');
  errores.push(`Cruce entre hojas muy bajo: ${(pctCruce * 100).toFixed(1)}% (minimo 95%). Sin cruce (${sinCruce.length} de ${backlog.length}): ${ejemplos}`);
}

const conValorOf = info.filter(r => esNumero(r['Valor OF'])).length;
const pctValorOf = info.length ? conValorOf / info.length : 0;
if (pctValorOf < 0.5) errores.push(`Muy pocos Valor OF numericos: ${(pctValorOf * 100).toFixed(1)}% (minimo 50%)`);

return [{ json: { ...data, _validacion: { valido: errores.length === 0, errores } } }];

function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

function ordenarClaves(obj) {
  if (Array.isArray(obj)) return obj.map(ordenarClaves);
  if (obj && typeof obj === 'object') {
    return Object.keys(obj).sort().reduce((acc, k) => {
      acc[k] = ordenarClaves(obj[k]);
      return acc;
    }, {});
  }
  return obj;
}

const data = $json;
if ((!Number.isInteger(data._fuente?.anio_forecast) || data._fuente.anio_forecast < 2000 || data._fuente.anio_forecast > 2100) || data._fuente?.modo !== 'cargar'
    || typeof data._fuente?.archivo_id !== 'string' || !data._fuente.archivo_id.trim()) {
  throw new Error('Escritura bloqueada: requiere año valido, modo cargar y archivo_id.');
}
// Subir VERSION_ETL cada vez que cambie qué se extrae o cómo se calcula: así
// la misma planilla genera una carga nueva en vez de deduplicarse contra una
// carga hecha con la lógica anterior.
const VERSION_ETL = 5;
const payload = { version: VERSION_ETL, anio_forecast: data._fuente.anio_forecast,
  archivo_id: data._fuente.archivo_id, InfoProyectos: data.InfoProyectos, Backlog: data.Backlog };
const canonical = JSON.stringify(ordenarClaves(payload));
const hash = cyrb53(canonical);

return [{ json: { ...data, _hash: hash } }];

function sqlBool(v) {
  return v === true ? 'TRUE' : v === false ? 'FALSE' : 'NULL::boolean';
}

function parsearBooleano(v) {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).toLowerCase().trim();
  if (s === 'true' || s === '1' || s === 'sí' || s === 'si') return true;
  if (s === 'false' || s === '0' || s === 'no') return false;
  return null;
}


function parsearProjectStatus(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toLowerCase();
  if (s === 'red' || s === 'rojo') return 'Red';
  if (s === 'yellow' || s === 'amarillo') return 'Yellow';
  if (s === 'green' || s === 'verde') return 'Green';
  return null;
}

function sqlStr(v) {
  if (v === null || v === undefined || v === '' || v === '#N/A') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
// En un VALUES sin montos, NULL sin tipo se infiere como text.
function sqlNum(v, ausente = 'NULL::numeric') {
  if (v === null || v === undefined || v === '' || v === '#N/A') return ausente;
  const n = Number(v);
  const LIMITE_MONTO = 100000000;
  if (!Number.isFinite(n) || Math.abs(n) > LIMITE_MONTO) return ausente;
  return String(n);
}
function sqlInt(v) {
  if (v === null || v === undefined) return 'NULL::integer';
  return String(Math.round(v));
}
function sqlDate(v) {
  if (v === null || v === undefined || v === '') return 'NULL::date';
  return "'" + v + "'::date";
}

const data = $('Calcular Hash').item.json;
if ((!Number.isInteger(data._fuente?.anio_forecast) || data._fuente.anio_forecast < 2000 || data._fuente.anio_forecast > 2100) || data._fuente?.modo !== 'cargar'
    || typeof data._fuente?.archivo_id !== 'string' || !data._fuente.archivo_id.trim()) {
  throw new Error('Escritura bloqueada: requiere año valido, modo cargar y archivo_id.');
}
const info = data.InfoProyectos || [];
const backlog = data.Backlog || [];
if (backlog.some(r => r._forecast?.anio_forecast !== data._fuente.anio_forecast)) {
  throw new Error('Falta normalizar o hay filas de otro año. Ejecuta desde Manual Trigger.');
}
const hash = data._hash;
const fechaReferencia = data.fechaReferencia;
// Una misma corrida actualiza varias fuentes: un solo corte para el usuario.
const ejecucionId = typeof $execution !== 'undefined' && $execution.id
  ? String(typeof $workflow !== 'undefined' ? $workflow.id : 'forecast') + ':' + String($execution.id) : null;

const proyectosPorClave = new Map();
for (const row of info) proyectosPorClave.set(row._clave, row);
for (const row of backlog) if (!proyectosPorClave.has(row._clave)) proyectosPorClave.set(row._clave, row);

const backlogPorClave = new Map();
for (const row of backlog) if (!backlogPorClave.has(row._clave)) backlogPorClave.set(row._clave, row);
const backlogSinDuplicados = Array.from(backlogPorClave.values());

const proyectoValues = [];
for (const [clave, row] of proyectosPorClave) {
  proyectoValues.push(`(${sqlStr(clave)}, ${sqlStr(row['# PA'])}, ${sqlStr(row['Project ID'])}, ${sqlStr(row['# Opp.'])}, `
    + `${sqlStr(row['Nombre del Proyecto'])}, ${sqlStr(row['Cliente'])}, ${sqlStr(row['PM/Líder'])}, ${sqlStr(row['PM/Líder PSA'])}, `
    + `${sqlStr(row['Zona'])}, ${sqlStr(row['Pais'])}, ${sqlStr(row['Vendedor'])}, ${sqlStr(row['TSM'])}, `
    + `${sqlStr(row['Billing Type'])}, ${sqlStr(row['Billing Arrengement'])}, ${sqlStr(row['Estado'])}, `
    + `${sqlNum(row['Valor OF'])}, ${sqlNum(row['Valor OF Anterior'])}, ${sqlNum(row['ACUMULADO A HOY'])}, `
    + `${sqlNum(row['Consumido 2025'])}, ${sqlNum(row['Backlog 2026'])}, ${sqlDate(row._fecha_fin_iso)}, `
    + `${sqlInt(row._dias_para_vencimiento)}, ${sqlNum(row._meses_transcurridos)}, ${sqlStr(row._estado_contrato)}, ${sqlStr(row['ESTATUS'])}, `
    + `${sqlBool(parsearBooleano(row._executive_watchlist))}, ${sqlStr(parsearProjectStatus(row._project_status))})`);
}

const sqlProyectosUpsert = `proyectos_upsert AS (
  INSERT INTO proyecto (
    clave, num_pa, project_id, num_opp, nombre, cliente, pm_lider, pm_lider_psa,
    zona, pais, vendedor, tsm, billing_type, billing_arrangement, estado,
    valor_of, valor_of_anterior, acumulado_a_hoy, consumido_2025, backlog_2026, fecha_fin,
    dias_para_vencimiento, meses_transcurridos, estado_contrato, estatus,
    executive_watchlist, project_status, primera_carga_id, ultima_carga_id
  )
  SELECT v.*, (SELECT id FROM nueva_carga), (SELECT id FROM nueva_carga)
  FROM (VALUES
${proyectoValues.join(',\n')}
  ) AS v(
    clave, num_pa, project_id, num_opp, nombre, cliente, pm_lider, pm_lider_psa,
    zona, pais, vendedor, tsm, billing_type, billing_arrangement, estado,
    valor_of, valor_of_anterior, acumulado_a_hoy, consumido_2025, backlog_2026, fecha_fin,
    dias_para_vencimiento, meses_transcurridos, estado_contrato, estatus,
    executive_watchlist, project_status
  )
  ON CONFLICT (clave) DO UPDATE SET
    num_pa = EXCLUDED.num_pa, project_id = EXCLUDED.project_id, num_opp = EXCLUDED.num_opp,
    nombre = EXCLUDED.nombre, cliente = EXCLUDED.cliente, pm_lider = EXCLUDED.pm_lider, pm_lider_psa = EXCLUDED.pm_lider_psa,
    zona = EXCLUDED.zona, pais = EXCLUDED.pais, vendedor = EXCLUDED.vendedor, tsm = EXCLUDED.tsm,
    billing_type = EXCLUDED.billing_type, billing_arrangement = EXCLUDED.billing_arrangement, estado = EXCLUDED.estado,
    valor_of = EXCLUDED.valor_of, valor_of_anterior = EXCLUDED.valor_of_anterior, acumulado_a_hoy = EXCLUDED.acumulado_a_hoy,
    consumido_2025 = EXCLUDED.consumido_2025, backlog_2026 = EXCLUDED.backlog_2026, fecha_fin = EXCLUDED.fecha_fin,
    dias_para_vencimiento = EXCLUDED.dias_para_vencimiento, meses_transcurridos = EXCLUDED.meses_transcurridos,
    estado_contrato = EXCLUDED.estado_contrato, estatus = EXCLUDED.estatus,
    executive_watchlist = EXCLUDED.executive_watchlist, project_status = EXCLUDED.project_status,
    ultima_carga_id = (SELECT id FROM nueva_carga), actualizado_en = now()
  RETURNING id, clave
)`;

const MESES = [
  ['Enero', 1, 'Upside'], ['Febrero', 2, 'Upside_1'], ['Marzo', 3, 'Upside_2'],
  ['Abril', 4, 'Upside_3'], ['Mayo', 5, 'Upside_4'], ['Junio', 6, 'Upside_5'],
  ['Julio', 7, 'Upside_6'], ['Agosto', 8, 'Upside_7'], ['Septiembre', 9, 'Upside_8'],
  ['Octubre', 10, 'Upside_9'], ['Noviembre', 11, 'Upside_10'], ['Diciembre', 12, 'Upside_11'],
];

const revenueMesValues = [];
for (const row of backlogSinDuplicados) {
  for (const [mesNombre, mesNum, upsideCol] of MESES) {
    const commit = sqlNum(row._forecast.meses[mesNum - 1].commit, '0');
    const upside = sqlNum(row._forecast.meses[mesNum - 1].upside, '0');
    revenueMesValues.push(`(${sqlStr(row._clave)}, ${mesNum}, ${commit}, ${upside})`);
  }
}

const sqlRevenueMes = `revenue_mes_insert AS (
  INSERT INTO revenue_mes (carga_id, proyecto_id, mes, commit_usd, upside_usd)
  SELECT (SELECT id FROM nueva_carga), pu.id, v.mes, v.commit_usd, v.upside_usd
  FROM (VALUES
${revenueMesValues.join(',\n')}
  ) AS v(clave, mes, commit_usd, upside_usd)
  JOIN proyectos_upsert pu ON pu.clave = v.clave
  RETURNING proyecto_id, mes, commit_usd, upside_usd
)`;

const revenueAnualValues = backlogSinDuplicados.map(row => {
  // FIX: valor_of debe venir de BackLog NOLA (row['Valor OF']), NO de Info Proyectos
  const valorOf = sqlNum(row._forecast.valor_of);
  return `(${sqlStr(row._clave)}, ${valorOf}, ${sqlNum(row._forecast.acumulado_anterior)}, ${sqlNum(row._forecast.backlog)}, ${sqlNum(row._forecast.total_ejecutado)})`;
});

const sqlRevenueAnual = `revenue_anual_insert AS (
  INSERT INTO revenue_anual (carga_id, proyecto_id, valor_of, acum_2025, backlog, total_ejecutado_acumulado)
  SELECT (SELECT id FROM nueva_carga), pu.id, v.valor_of::numeric, v.acum_2025::numeric, v.backlog::numeric, v.total_ejecutado::numeric
  FROM (VALUES
${revenueAnualValues.join(',\n')}
  ) AS v(clave, valor_of, acum_2025, backlog, total_ejecutado)
  JOIN proyectos_upsert pu ON pu.clave = v.clave
  RETURNING 1
)`;

const sqlMovimiento = `movimiento_insert AS (
  INSERT INTO movimiento (carga_id, carga_previa_id, proyecto_id, mes, tipo, monto, commit_anterior, commit_nuevo, upside_anterior, upside_nuevo)
  SELECT
    (SELECT id FROM nueva_carga), (SELECT id FROM carga_previa),
    n.proyecto_id, n.mes,
    CASE WHEN n.commit_usd > COALESCE(a.commit_usd, 0) THEN 'upside_a_commit' ELSE 'commit_a_upside' END,
    abs(n.commit_usd - COALESCE(a.commit_usd, 0)),
    a.commit_usd, n.commit_usd, a.upside_usd, n.upside_usd
  FROM revenue_mes_insert n
  LEFT JOIN revenue_mes a
    ON a.carga_id = (SELECT id FROM carga_previa) AND a.proyecto_id = n.proyecto_id AND a.mes = n.mes
  WHERE (SELECT id FROM carga_previa) IS NOT NULL
    AND abs(n.commit_usd - COALESCE(a.commit_usd, 0)) >= 1.0
  RETURNING 1
)`;

const sql = `BEGIN;
WITH
nueva_carga AS (
  INSERT INTO carga (archivo_nombre, datos_hash, fecha_referencia, filas_info, filas_backlog, anio_forecast, archivo_id, ejecucion_id)
  VALUES (${sqlStr(data._fuente.archivo_nombre)}, ${sqlStr(hash)}, ${sqlStr(fechaReferencia)}, ${info.length}, ${backlog.length}, ${sqlInt(data._fuente.anio_forecast)}, ${sqlStr(data._fuente.archivo_id)}, ${sqlStr(ejecucionId)})
  RETURNING id, anio_forecast, archivo_id, archivo_nombre
),
carga_previa AS (
  SELECT id FROM carga WHERE id < (SELECT id FROM nueva_carga)
    AND anio_forecast = ${sqlInt(data._fuente.anio_forecast)}
    AND archivo_id = ${sqlStr(data._fuente.archivo_id)}
  ORDER BY id DESC LIMIT 1
),
${sqlProyectosUpsert},
${sqlRevenueMes},
${sqlRevenueAnual},
${sqlMovimiento}
SELECT
  (SELECT id FROM nueva_carga) AS carga_id,
  (SELECT anio_forecast FROM nueva_carga) AS anio_forecast,
  (SELECT archivo_id FROM nueva_carga) AS archivo_id,
  (SELECT archivo_nombre FROM nueva_carga) AS archivo_nombre,
  (SELECT count(*) FROM proyectos_upsert) AS proyectos,
  (SELECT count(*) FROM revenue_mes_insert) AS filas_revenue,
  (SELECT count(*) FROM movimiento_insert) AS movimientos;
COMMIT;`;

return [{ json: { sql } }];

// Registrar aqui cada Excel nuevo. Los años anteriores se mantienen en la base.
const MODO = 'cargar'; // 'validar' revisa todas las fuentes sin escribir PostgreSQL.
const archivos = {
  2026: { archivo_id: '1_NNst0wIKXAlCa7fu8RRiBFAahcXzvuGEEt5IAhm-co', archivo_nombre: 'CLOUD FORECAST GENERAL - NOLA FY26' },
  2027: { archivo_id: '13ULKx3-9MmFrU6suvm8jSgIwIKsBh44wLH7i_l10tSE', archivo_nombre: '27-CLOUD FORECAST GENERAL - NOLA FY27' },
};
const fuentes = Object.fromEntries(Object.entries(archivos).map(([key, archivo]) => {
  const anio = Number(key);
  const anteriores = Array.from({length:Math.max(0,anio-2025)},(_,i)=>2025+i).join('-');
  const completo = anteriores + '-' + anio;
  return [anio, { ...archivo, campos: archivo.campos || {
    valor_of: ['Valor OF'],
    acumulado_anterior: anio === 2026 ? ['Acum 2025'] : ['Total Ejecutado Acumulado ' + anteriores, 'Total Ejecutado Acumulado 2025-' + (anio - 1), 'Acumulado anterior'],
    backlog: ['Backlog ' + anio, ...(anio === 2026 ? ['Backlog'] : [])],
    total_ejecutado: ['TOTAL EJECUTADO ACUMULADO ' + completo, 'TOTAL EJECUTADO ACUMULADO ' + completo + ' (COPIAR)', 'TOTAL EJECUTADO ACUMULADO 2025-' + anio, 'TOTAL EJECUTADO ACUMULADO 2025-' + anio + ' (COPIAR)', ...(anio === 2026 ? ['TOTAL EJECUTADO ACUMULADO'] : [])],
  } }];
}));
const ANIOS_FORECAST = Object.keys(fuentes).map(Number).sort((a,b) => a-b);
if (!['cargar', 'validar'].includes(MODO)) throw new Error('Modo de forecast no valido.');
if (!ANIOS_FORECAST.length || new Set(ANIOS_FORECAST).size !== ANIOS_FORECAST.length
    || ANIOS_FORECAST.some(anio => !fuentes[anio])) {
  throw new Error('Seleccion de años de forecast no valida o duplicada.');
}
return ANIOS_FORECAST.map(anio => ({ json: {
  _fuente: { anio_forecast: anio, modo: MODO, ...fuentes[anio] },
} }));

const data = $json;
const fuente = data._fuente;
if ((!Number.isInteger(fuente?.anio_forecast) || fuente.anio_forecast < 2000 || fuente.anio_forecast > 2100) || !fuente.campos) {
  throw new Error('Falta configurar la fuente. Ejecuta desde Manual Trigger.');
}
const normalizar = valor => String(valor).replace(/\s+/g, ' ').trim().toUpperCase();
const numero = valor => {
  if (valor === null || valor === undefined || typeof valor === 'boolean' || String(valor).trim() === '') return null;
  const n = Number(valor);
  return Number.isFinite(n) && Math.abs(n) <= 100000000 ? n : null;
};
function leer(fila, nombres) {
  for (const nombre of nombres) {
    const clave = Object.keys(fila).find(k => normalizar(k) === normalizar(nombre));
    if (clave !== undefined) return fila[clave];
  }
  return null;
}
const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const cabeceras = new Set((data.Backlog || []).flatMap(r => Object.keys(r).map(normalizar)));
const requeridas = {
  ...fuente.campos,
  ...Object.fromEntries(meses.map(m => [m, [m]])),
  ...Object.fromEntries(meses.map((m, i) => [m + '_upside', [i ? 'Upside_' + i : 'Upside']])),
};
const faltantes = Object.entries(requeridas).filter(([, nombres]) => !nombres.some(n => cabeceras.has(normalizar(n)))).map(([campo]) => campo);
// No permitir que un archivo FY27 se procese por error como FY26 o viceversa.
const cabeceraOtroAnio = [...cabeceras].some(c => /^BACKLOG 20\d{2}$/.test(c) && c !== 'BACKLOG ' + fuente.anio_forecast);
const backlog = (data.Backlog || []).map(row => ({
  ...row,
  _forecast: {
    anio_forecast: fuente.anio_forecast,
    ...Object.fromEntries(Object.entries(fuente.campos).map(([campo, nombres]) => [campo, numero(leer(row, nombres))])),
    meses: meses.map((m, i) => ({
      mes: i + 1,
      commit: numero(leer(row, [m])),
      upside: numero(leer(row, [i ? 'Upside_' + i : 'Upside'])),
    })),
  },
}));
return [{ json: {
  ...data,
  Backlog: backlog,
  _esquema_forecast: { anio_forecast: fuente.anio_forecast, faltantes, cabeceraOtroAnio },
} }];

const data = $json;
const campos = ['valor_of','acumulado_anterior','backlog','total_ejecutado'];
return [{ json: {
  modo: 'validar',
  anio_forecast: data._fuente.anio_forecast,
  archivo_id: data._fuente.archivo_id,
  archivo_nombre: data._fuente.archivo_nombre,
  valido: data._validacion.valido,
  filas_info: data.InfoProyectos.length,
  filas_backlog: data.Backlog.length,
  cobertura_financiera: Object.fromEntries(campos.map(c => [c, {
    con_dato: data.Backlog.filter(r => r._forecast[c] !== null).length,
    sin_dato: data.Backlog.filter(r => r._forecast[c] === null).length,
  }])),
  muestras: data.Backlog.slice(0, 3).map(r => ({ pa: r['# PA'] ?? null, ...r._forecast })),
  escritura_postgres: false,
  aviso: 'Validacion terminada. No se consultaron ni modificaron cargas, proyectos o movimientos de PostgreSQL. El dashboard y el agente mantienen FY26.',
} }];

const items = $input.all();
if (items.length !== 1 || (!Number.isInteger(items[0]?.json._fuente?.anio_forecast) || items[0].json._fuente.anio_forecast < 2000 || items[0].json._fuente.anio_forecast > 2100)) throw new Error('Se requiere una sola fuente por iteracion. Ejecuta desde Manual Trigger.');
return items;

// PostgreSQL devuelve la identidad de la captura; no dependemos de pairedItem.
const cargas = $input.all().map(i => i.json).filter(r => r.carga_id != null);
if (cargas.length !== 1) throw new Error('PostgreSQL debe devolver exactamente una carga_id.');
const carga = cargas[0];
const anio = Number(carga.anio_forecast);
if ((!Number.isInteger(anio) || anio < 2000 || anio > 2100) || typeof carga.archivo_id !== 'string' || !carga.archivo_id) {
  throw new Error('La respuesta SQL no identifica año/fuente. Actualiza tambien Construir SQL de Carga.');
}
return [{ json: { anio_forecast: anio, archivo_id: carga.archivo_id, archivo_nombre: carga.archivo_nombre,
  estado: 'cargado', escritura_postgres: true, carga_id: carga.carga_id,
  proyectos: carga.proyectos, filas_revenue: carga.filas_revenue, movimientos: carga.movimientos } }];

const fuentes = $input.all().map(i => i.json);
const esperadas = $('Configurar Fuente Forecast').all().map(i => i.json._fuente.anio_forecast);
if (fuentes.length !== esperadas.length || esperadas.some(anio => fuentes.filter(f => f.anio_forecast === anio).length !== 1)) throw new Error('Resumen incompleto o fuentes duplicadas. Revisa la ejecucion.');
return [{ json: { total_fuentes: fuentes.length, cargas_nuevas: fuentes.filter(f => f.estado === 'cargado').length, sin_cambios: fuentes.filter(f => f.estado === 'sin_cambios').length, solo_validadas: fuentes.filter(f => f.modo === 'validar').length, fuentes } }];
